MIME-Version: 1.0
Content-Type: multipart/mixed; boundary="ptf-outer-1"

This is a Potentia Transmission Format (PTF) document combining the selected widgets.
--ptf-outer-1
Content-Type: text/javascript; charset=utf-8
Content-Disposition: attachment; filename="fluid.demos.ai.closestNoteImage"
Content-Description: layer

fluid.def("fluid.demos.ai.closestNoteImage", {
    // Combined widget: the image generator is dominant and visible; the closest-note finder is a supplier
    // hidden inside it. Move the widget close to a sticky note and press "Find Image" to generate an image
    // of that note's text.
    $layers: ["fluid.demos.imageGenerator", "fluid.topLevelWidget"],
    // Hidden supplier: computes the text of the nearest sticky note from the widget's placed bounds
    finder: {
        $component: {
            $layers: "fluid.demos.closestNoteFinder",
            view: "{closestNoteImage}.view"
        }
    },
    // The generator's prompt input takes the nearest note's text (it may still be typed over)
    state: {
        prompt: "{finder}.noteText"
    }
});
--ptf-outer-1
Content-Type: multipart/mixed; boundary="ptf-inner-1"
Content-Disposition: attachment; filename="shape:noteImageGen"
Content-Description: component

--ptf-inner-1
Content-Type: application/json; charset=utf-8
Content-Disposition: attachment; filename="/"
Content-Description: potentia

{
    "$layers": [
        "fluid.demos.ai.closestNoteImage"
    ]
}
--ptf-inner-1
Content-Type: application/json; charset=utf-8
Content-Disposition: attachment; filename="shape"
Content-Description: shape

{"x": 380, "y": 360, "w": 360, "h": 460}
--ptf-inner-1--
--ptf-outer-1--
